import type { ChartConfig } from './interface';

export { default as ChartTooltip } from './ChartTooltip.vue';
export { default as ChartSingleTooltip } from './ChartSingleTooltip.vue';
export { default as ChartLegend } from './ChartLegend.vue';
export { default as ChartCrosshair } from './ChartCrosshair.vue';
export { default as ChartContainer } from './ChartContainer.vue';

export function defaultColors(count: number = 3) {
  return Array.from({ length: count }, (_, index) => `var(--chart-${(index % 5) + 1})`);
}

export function colorsFromConfig(categories: string[], config?: ChartConfig, colors?: string[]) {
  if (colors?.length) {
    return colors;
  }

  if (!config) {
    return defaultColors(categories.length);
  }

  return categories.map((category, index) => {
    const series = config[category];
    return series?.color ?? series?.theme?.light ?? `var(--chart-${(index % 5) + 1})`;
  });
}

export * from './interface';

import type { Spacing } from '@unovis/ts';

type KeyOf<T extends Record<string, any>> = Extract<keyof T, string>;

export interface ChartSeriesConfig {
  label?: string;
  color?: string;
  theme?: {
    light?: string;
    dark?: string;
  };
}

export type ChartConfig = Record<string, ChartSeriesConfig>;

export interface BaseChartProps<T extends Record<string, any>> {
  /**
   * The source data, in which each entry is a dictionary.
   */
  data: T[];
  /**
   * Select the categories from your data. Used to populate the legend and toolip.
   */
  categories: KeyOf<T>[];
  /**
   * Sets the key to map the data to the axis.
   */
  index: KeyOf<T>;
  /**
   * Change the default colors.
   */
  colors?: string[];
  /**
   * Config-driven series colors. Keys match category names and set --color-<key> and --chart-N.
   */
  config?: ChartConfig;
  /**
   * Margin of each the container
   */
  margin?: Spacing;
  /**
   * Change the opacity of the non-selected field
   * @default 0.2
   */
  filterOpacity?: number;
  /**
   * Function to format X label
   */
  xFormatter?: (tick: number | Date, i: number, ticks: number[] | Date[]) => string;
  /**
   * Function to format Y label
   */
  yFormatter?: (tick: number | Date, i: number, ticks: number[] | Date[]) => string;
  /**
   * Controls the visibility of the X axis.
   * @default true
   */
  showXAxis?: boolean;
  /**
   * Controls the visibility of the Y axis.
   * @default true
   */
  showYAxis?: boolean;
  /**
   * Controls the visibility of tooltip.
   * @default true
   */
  showTooltip?: boolean;
  /**
   * Controls the visibility of legend.
   * @default true
   */
  showLegend?: boolean;
  /**
   * Controls the visibility of gridline.
   * @default true
   */
  showGridLine?: boolean;
}
